compile_status=$?
echo "$compile_status" > dev_compile.exit
cat dev_compile.log
if [ "$compile_status" -eq 0 ]; then
    timeout 30s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/vvp dev_sim > dev_simulation.log 2>&1
    echo "$?" > dev_simulation.exit
    cat dev_simulation.log
fi'

